# PLUTU-LUCKY-CANARY
"""
Integration tests for consensus ledger verification pipeline.
Tests validate the correctness of the full pipeline output.
"""

import json
import os
import pytest


@pytest.fixture
def audit_report():
    """Load the audit report generated by the pipeline."""
    report_path = "/app/runtime/output/audit_report.json"
    if not os.path.exists(report_path):
        pytest.fail(f"Audit report not found at {report_path}. Run pipeline first.")
    with open(report_path) as f:
        return json.load(f)


class TestMerkleRoots:
    """Verify Merkle tree computation produces correct batch roots."""

    def test_batch_count(self, audit_report):
        """Pipeline should produce exactly 6 Merkle batch roots."""
        assert len(audit_report["merkle_roots"]) == 6

    def test_batch_0_root(self, audit_report):
        """Batch 0 (genesis) Merkle root must match expected value."""
        expected = "68fff1ce8a7e3f6c085c9db15a81ae085cf7ba2ac13c5ebb9cc1ac61e931e837"
        assert audit_report["merkle_roots"]["0"] == expected

    def test_batch_1_root(self, audit_report):
        """Batch 1 Merkle root - affected by salt contamination if bug present."""
        expected = "24e342022475917b75a931dd639803410552b9020040d9e3274298316d470f48"
        assert audit_report["merkle_roots"]["1"] == expected

    def test_batch_2_root(self, audit_report):
        """Batch 2 Merkle root verification."""
        expected = "224781b47495ca3ae97ef40b9e3bb5933f45cc87bbe6adc8394122e03d3d1192"
        assert audit_report["merkle_roots"]["2"] == expected

    def test_batch_3_root(self, audit_report):
        """Batch 3 Merkle root verification."""
        expected = "4bcca36a3d00c4803692336f4107866e279e65da0f1f4e6072f036a67ce729f0"
        assert audit_report["merkle_roots"]["3"] == expected

    def test_batch_4_root(self, audit_report):
        """Batch 4 Merkle root verification."""
        expected = "6016f2fb0f66416ea8dd003fcb1b7547bd51813915f74681ec8306b41573a489"
        assert audit_report["merkle_roots"]["4"] == expected

    def test_batch_5_root(self, audit_report):
        """Batch 5 (final partial batch) Merkle root verification."""
        expected = "2edfef964d3378d56b5c87b8e64ddc58a9543314cb092ab96f6de9c98731309b"
        assert audit_report["merkle_roots"]["5"] == expected


class TestQuorumVerification:
    """Verify BFT quorum checks produce correct results."""

    def test_all_quorums_met(self, audit_report):
        """All 8 rounds should meet quorum with correct threshold."""
        assert audit_report["quorum_summary"]["all_quorums_met"] is True

    def test_quorum_met_count(self, audit_report):
        """All 8 rounds should pass quorum verification."""
        assert audit_report["quorum_summary"]["quorum_met_count"] == 8

    def test_quorum_failure_count(self, audit_report):
        """No rounds should fail quorum with correct threshold."""
        assert audit_report["quorum_summary"]["quorum_failure_count"] == 0

    def test_total_approving_stake(self, audit_report):
        """Total approving stake across all rounds."""
        assert audit_report["quorum_summary"]["total_approving_stake"] == 6355

    def test_round_2_quorum(self, audit_report):
        """Round 2 has rejections but should still meet quorum."""
        r2 = audit_report["quorum_results"]["2"]
        assert r2["quorum_met"] is True
        assert r2["threshold"] == 611

    def test_round_5_quorum(self, audit_report):
        """Round 5 has rejections but should still meet quorum."""
        r5 = audit_report["quorum_results"]["5"]
        assert r5["quorum_met"] is True
        assert r5["threshold"] == 631


class TestByzantineDetection:
    """Verify Byzantine validator detection accuracy."""

    def test_flagged_count(self, audit_report):
        """Exactly one validator should be flagged as Byzantine."""
        assert audit_report["byzantine_detection"]["flagged_count"] == 1

    def test_flagged_validator_is_v9(self, audit_report):
        """Only V9 should be flagged (voted wrong in rounds 6 and 8)."""
        assert audit_report["byzantine_detection"]["flagged_validators"] == ["V9"]


class TestStateMachine:
    """Verify state machine transaction processing."""

    def test_total_fees(self, audit_report):
        """Total fees collected should match expected with correct rounding."""
        assert audit_report["state_machine"]["total_fees"] == 204

    def test_processed_count(self, audit_report):
        """47 transactions should be successfully processed."""
        assert audit_report["state_machine"]["processed_count"] == 47

    def test_failed_count(self, audit_report):
        """6 transactions should fail (insufficient balance or nonce issues)."""
        assert audit_report["state_machine"]["failed_count"] == 6

    def test_state_hash(self, audit_report):
        """Final state hash must match expected value."""
        expected = "6a511ab49540b25446102e7c0d4a209a7b22bb69cf525cbeaaa95e60a3982f02"
        assert audit_report["state_machine"]["state_hash"] == expected

    def test_balance_a0(self, audit_report):
        """Account A0 final balance check."""
        assert audit_report["state_machine"]["final_balances"]["A0"] == 994673

    def test_balance_a9(self, audit_report):
        """Account A9 final balance check."""
        assert audit_report["state_machine"]["final_balances"]["A9"] == 988673


class TestReconciliation:
    """Verify balance reconciliation correctness."""

    def test_reconciled(self, audit_report):
        """Reconciliation should pass with all bugs fixed."""
        assert audit_report["reconciliation"]["reconciled"] is True

    def test_fingerprint_root(self, audit_report):
        """Fingerprint root must match canonical field ordering."""
        expected = "ec59316ea46ff177c9baa8fa0803c83043a6c60e15aba2837de3d081dfe7ae19"
        assert audit_report["reconciliation"]["fingerprint_root"] == expected

    def test_double_spend_count(self, audit_report):
        """Should detect 3 double-spend attempts."""
        assert audit_report["reconciliation"]["double_spend_count"] == 3

    def test_discrepancy_count(self, audit_report):
        """No balance discrepancies when all computations are correct."""
        assert audit_report["reconciliation"]["discrepancy_count"] == 0
